Plan:
Read the ZORD sheet and build a per-material list of unique “Valid to” dates in sheet order, formatted as DD/MM/YYYY. For each row 2–10 in the Volym sheet, join the matching dates with commas and write the resulting text into column I. Save the copied workbook with only the answer cells changed.

```python
import shutil
import openpyxl
import datetime

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws_vals = vals["Volym P5_P6_2023"]
zws_vals = vals["ZORD"]
ws = wb["Volym P5_P6_2023"]

def format_date(value):
    if value is None:
        return None

    if isinstance(value, datetime.datetime):
        return value.strftime("%d/%m/%Y")

    if isinstance(value, datetime.date):
        return datetime.datetime(value.year, value.month, value.day).strftime("%d/%m/%Y")

    if isinstance(value, bool):
        return None

    if isinstance(value, (int, float)):
        base = datetime.datetime(1899, 12, 30)
        return (base + datetime.timedelta(days=float(value))).strftime("%d/%m/%Y")

    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None

        try:
            return datetime.datetime.fromisoformat(s).strftime("%d/%m/%Y")
        except ValueError:
            pass

        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y",
            "%d-%m-%Y",
        ):
            try:
                return datetime.datetime.strptime(s, fmt).strftime("%d/%m/%Y")
            except ValueError:
                pass

        try:
            base = datetime.datetime(1899, 12, 30)
            return (base + datetime.timedelta(days=float(s))).strftime("%d/%m/%Y")
        except Exception:
            return s

    return str(value)

dates_by_material = {}

for row in zws_vals.iter_rows(min_row=2, values_only=True):
    if not row:
        continue

    material = row[0]
    valid_to = row[2] if len(row) > 2 else None

    if material is None or valid_to is None:
        continue

    key = str(material).strip()
    date_str = format_date(valid_to)

    if not date_str:
        continue

    lst = dates_by_material.setdefault(key, [])
    if date_str not in lst:
        lst.append(date_str)

for r in range(2, 11):
    material = vws_vals.cell(row=r, column=1).value
    key = str(material).strip() if material is not None else ""

    joined = ",".join(dates_by_material.get(key, []))
    ws.cell(row=r, column=9).value = joined.strip() if joined else None

    print(r, ws.cell(row=r, column=9).value)

wb.save(OUT)
